pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Prioritize Best-Fit: Lower post_residual is usually better, but we want to avoid 
    // creating "slivers" (very small residuals that nothing can fit into).
    // Penalize post_residuals that are too small to fit any items (assuming min item size ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0; 
    }

    // 2. 2-Step Lookahead: If the next item fits perfectly into this post_residual, 
    // reward this bin heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            // Reward bins that leave a gap of 0 or a very large gap (easier to fill later)
            // Penalize mid-range gaps that are hard to fill.
            score -= (100.0 - (gap as f64 * 2.0));
        } else {
            // If next item does not fit, penalize this bin slightly relative to others
            score += 15.0;
        }
    }

    // 3. Global Packing Efficiency: If we are nearing the end of the stream, 
    // be more aggressive about filling existing bins to minimize open_bins_count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 5.0;
    }

    // 4. Mean Residual Balancing: Avoid bins that deviate too far from the average 
    // efficiency of the system.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 5. New Bin Penalty: If bin_residual == bin_capacity, this is a "new bin" candidate.
    // Only open a new bin if the current fit is catastrophic (high post_residual).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless existing bins are extremely crowded
        score += 65.0 - (open_bins_count as f64 * 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let res_ratio = post_res / bin_capacity as f64;

    // Penalize small residuals (dead space) quadratically, but weight by stream progress.
    // As we approach the end of the stream, we become more aggressive about filling gaps.
    let dead_space_penalty = (1.0 - res_ratio).powi(2) * 50.0 * (1.0 + progress);

    // Favor bins that align with the next item's size (lookahead)
    let lookahead_penalty = if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit reward
            -20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64)
        } else {
            // Cannot fit next item, slight penalty
            10.0 * (next_item_size as f64 / bin_capacity as f64)
        }
    } else {
        0.0
    };

    // Penalize opening new bins, but scale by remaining items to allow flexibility early on.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        // If it's the only fitting bin, don't penalize too hard, otherwise discourage new bins.
        if fitting_bins_count == 0 { 5.0 } else { 40.0 * (1.0 - progress * 0.5) }
    } else {
        0.0
    };

    // Combine factors:
    // 1. Post-residual (lower is better, but avoid creating tiny unusable shards)
    // 2. Dead space penalty
    // 3. Lookahead alignment
    // 4. New bin avoidance
    let score = post_res + dead_space_penalty + lookahead_penalty + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit strategy)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: force it to be only if no better options exist
    if is_new_bin {
        score += 35.0 + (progress * 15.0);
    } else {
        // Penalty for creating 'dead space' (small residuals that likely won't fit future items)
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }

        // Lookahead: if the next item fits into the current post_residual, prioritize this bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }

        // Contextual pressure: if we have many bins open, favor filling them tighter
        if open_bins_count > 5 {
            score += (open_bins_count as f64) * 0.5;
        }

        // If this is the only bin that can fit the item, prioritize it to avoid new bin creation
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // Deviation penalty: if the post-residual is far from the mean, it might be an outlier
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    score
}

