    let post = post_residual as f64;

    // Base score is the residual space: lower is generally better (Best Fit).
    let mut score = post;

    // Penalty for creating a "fragment" (small, unusable space) that increases as the stream progresses.
    // We penalize residuals in the [1, 9] range heavily, as they are unlikely to fit future items.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0 * (1.0 + progress);
