    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // New bin threshold control:
    // If we are evaluating a brand-new bin (bin_residual == bin_capacity),
    // we set a high baseline score to ensure we only open a new bin if the fit in 
    // existing bins is exceptionally poor (e.g., creating too many fragments).
    if bin_residual == bin_capacity {
        // As the stream progresses, we become more conservative about opening new bins.
        score = 25.0 + (progress * 20.0);
    }

    // Global efficiency pressure: 
    // If many bins are open, penalize the creation of new ones or the choice of bins 
    // that increase the mean_residual significantly.
    score += (open_bins_count as f64 * 0.5) + (mean_residual * 0.2);

    score
}

