pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that cannot fit common item sizes (10-80).
    // Small residuals are dangerous; target residuals that match next_item_size.
    if post_residual > 0 {
        if post_residual < next_item_size {
            score += 50.0;
        } else if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // 2. Best-Fit Logic: Minimize post_residual, but heavily penalize dead space (1..9).
    // If a fit leaves a tiny sliver that is unlikely to be filled, punish it.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // 3. Last-Chance Logic: If this is the only bin that fits, prioritize it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // 4. New Bin Thresholding: Dynamic bias against opening new bins.
    // As the stream progresses, make opening a new bin increasingly expensive.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0);
    }

    // 5. Harmonic packing: Favor bins where the new residual is a multiple of 10.
    // This aligns with common item size increments.
    if post_residual % 10 == 0 {
        score -= 10.0;
    }

    // 6. Mean Residual Balancing: Avoid bins that deviate significantly from the mean.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}
